import React from 'react';
import { getCyberpunkColors } from '../Analysis/ComplaintTrackingChart';

const PageHeader = ({ title, subtitle }) => {
  const colors = getCyberpunkColors();
  
  return (
    <div className="w-full p-3 mb-3">
      <div className="flex items-center">
        <div className="mr-2 w-2 h-8" style={{ background: colors.neon.green, boxShadow: `0 0 10px ${colors.neon.green}` }}></div>
        {title}
      </div>
      {subtitle && (
        <div className="mt-1 ml-4 font-mono text-sm" style={{ color: colors.text.secondary }}>
          {subtitle}
        </div>
      )}
    </div>
  );
};

export default PageHeader;
